OLD_FACTORS = ["0.3", "0.45", "0.6", "0.8", "1", "1.25"]        # 0.3.0: the old defaults the one-time config update replaces
# 0.3.1 (Skyy 2026-10-15: "Yes, boost every rarity ~3x"): every kind's Lv 100 value x (0.2.x factor / 0.3) / 0.3.0 factor of ITS start
