BOOST_TARGET = 1.0 / float(OLD_FACTORS[0])


def _boost_stats(stats, rarity):
    _i = RARITIES.index(rarity)
    _m = BOOST_TARGET * float(OLD_FACTORS[_i]) / float(FACTORS[_i])
    _out = []
    for _p in stats.split(","):
        _k, _v = _p.split(":")
        _n = round(float(_v) * _m * 2.0) / 2.0
        _out.append("%s:%s" % (_k, str(int(_n)) if _n == int(_n) else repr(_n)))
    return ",".join(_out)


