def fx_life(path):
    """seconds until every particle of that system is gone, None = it never ends by itself (or cannot be read)"""
    try:
        d = vjson(path)
    except Exception:
        return None
    ents = d.get("Spawners") or []
    sl = d.get("LifeSpan")
    syslife = isinstance(sl, (int, float)) and sl > 0
    if not ents:
        return None
    worst = 0.0
    for e in ents:
        sp = _SPN.get(e.get("SpawnerId")) or []
        if len(sp) != 1:
            return None
        try:
            sd = vjson(sp[0])
        except Exception:
            return None
        pl = sd.get("ParticleLifeSpan") or {}
        plife = float(pl.get("Max", pl.get("Min", 0)) or 0)
        if syslife:
            emit = float(sl)
        else:
            if e.get("TotalSpawners", 1) in (-1, 0):
                return None
            tp = (sd.get("TotalParticles") or {}).get("Max")
            if tp is None or tp <= 0:
                if not (isinstance(sd.get("LifeSpan"), (int, float)) and sd["LifeSpan"] > 0):
                    return None
                emit = float(sd["LifeSpan"])
            else:
                rate = float((sd.get("SpawnRate") or {}).get("Min", 0) or 0)
                emit = 0.0 if sd.get("SpawnBurst") else (float(tp) / rate if rate > 0 else 99.0)
        worst = max(worst, float(e.get("StartDelay") or 0) + emit + plife)
    return worst


