    _e0 = (vjson(_PSN[_nm][0]).get("Spawners") or [{}])[0]
    AURA_OK.append("%s=%s" % (_nm, repr(round(float(((_e0.get("PositionOffset") or {}).get("Y")) or 0.0), 3))))
