# ---- the two roles, from vanilla data (Test_Pet's follow, Test_Fly's Fly controller, Empty_Role's empty instructions)
_tp, _tf, _er = vjson(ROLE_PATH["Test_Pet"]), vjson(ROLE_PATH["Test_Fly"]), vjson(ROLE_PATH["Empty_Role"])
assert _tp.get("Debug") == "DisplayState" and _tp.get("Invulnerable") is True and _tp.get("Type") == "Generic"


def _default_state(instrs):
    for i in instrs:
        sn = i.get("Sensor") or {}
        if sn.get("Type") == "State" and sn.get("State") == ".Default":
            return i["Instructions"]
        if "Instructions" in i:
            r = _default_state(i["Instructions"])
            if r is not None:
                return r
    return None


_follow = [i for i in _default_state(_tp["Instructions"]) if (i.get("Sensor") or {}).get("Type") in ("Player", "Target") and "BodyMotion" in i
           and "Filters" not in i["Sensor"] and "Actions" not in i]
assert [i["BodyMotion"]["Type"] for i in _follow] == ["Seek", "Teleport"] and _follow[0]["Sensor"].get("LockOnTarget") is True, _follow
_walk_mc = dict(_tp["MotionControllerList"][0])
assert _walk_mc.get("Type") == "Walk"
_walk_mc["MaxWalkSpeed"] = 6
ROLE_WALK_JSON = {"Type": "Generic", "Appearance": _tp["Appearance"], "Invulnerable": True, "DefaultPlayerAttitude": "Ignore",
                  "MotionControllerList": [_walk_mc], "MaxHealth": _tp["MaxHealth"],
                  # fix round: seek the owner (our locked target) first, Test_Pet's Player sensor only until the target is set; the
                  # role's own Teleport is dropped - it fired at ~15-19 blocks (P3), so pets.follow.teleport never applied to walkers
                  "Instructions": [{"Instructions": [{"Sensor": {"Type": "Target"}, "BodyMotion": dict(_follow[0]["BodyMotion"])}, _follow[0]]}],
                  "NameTranslationKey": _tp["NameTranslationKey"]}
assert _tf["MotionControllerList"][0].get("Type") == "Fly" and _er.get("Instructions") == [{}]
