F(cfgc, "public static volatile String ELEM_TXT = null;")
F(cfgc, "public static volatile java.util.HashMap ELEM_MAP = new java.util.HashMap();")
F(cfgc, "public static final String[] ELEM_NAMES = %s;" % jarr(EL.NAMES))
M(cfgc, r"""
public static String elemWord(String s) {
  if (s == null) return null;
  String t = s.trim();
  for (int i = 0; i < ELEM_NAMES.length; i++) if (ELEM_NAMES[i].equalsIgnoreCase(t)) return ELEM_NAMES[i];
  if (t.equalsIgnoreCase("Lightning")) return "Thunder";
  if (t.equalsIgnoreCase("Wind")) return "Air";
  if (t.length() == 0 || t.equalsIgnoreCase("none") || t.equals("-")) return "";
  return null;
}""")
M(cfgc, r"""
public static java.util.HashMap elemParse(String v) {
  java.util.HashMap m = new java.util.HashMap();
  if (v == null) return m;
  String[] ps = v.split(",");
  for (int i = 0; i < ps.length; i++) {
    String e = ps[i].trim();
    if (e.length() == 0) continue;
    int q = e.indexOf('=');
    String w = q > 0 ? elemWord(e.substring(q + 1)) : null;
    if (w == null) { @PKG@.PetsLog.warnOnce("petelem:" + e, "pets.element: '" + e + "' is not Kind=Element - skipped"); continue; }
    if (w.length() > 0) m.put(e.substring(0, q).trim().toLowerCase(), w);
  }
  return m;
}""")
M(cfgc, r"""
public static String elemOf(String kind) {
  if (kind == null) return null;
  String t = ELEMS;
  if (t != ELEM_TXT) { ELEM_MAP = elemParse(t); ELEM_TXT = t; }
  Object o = ELEM_MAP.get(kind.toLowerCase());
  return o instanceof String ? (String) o : null;
}""")
M(cfgc, r"""
public static String checkElem(String key, String value) {
  if (value == null) return null;
  String[] ps = value.split(",");
  for (int i = 0; i < ps.length; i++) {
    String e = ps[i].trim();
    if (e.length() == 0) continue;
    int q = e.indexOf('=');
    if (q <= 0) return "'" + e + "' needs Kind=Element.";
    if (elemWord(e.substring(q + 1)) == null) return "'" + e.substring(q + 1).trim() + "' is no element (Earth Thunder Water Fire Air none).";
  }
  return null;
}""")
M(cfgc, r"""
public static void applyTables(java.util.Properties p) {
  java.util.ArrayList ks = new java.util.ArrayList();
  java.util.HashMap looks = new java.util.HashMap();
  java.util.HashMap babies = new java.util.HashMap();
  java.util.HashMap roles = new java.util.HashMap();
  java.util.HashSet inFile = new java.util.HashSet();
  if (p != null) {
    java.util.ArrayList keys = new java.util.ArrayList(p.stringPropertyNames());
    java.util.Collections.sort(keys);
    for (int i = 0; i < keys.size(); i++) {
      String k = (String) keys.get(i);
      if (k.startsWith("look.") && k.length() > 5) {
        String[] lv = @PKG@.PetLook.parse(p.getProperty(k), "/");
        if (lv == null) { @PKG@.PetsLog.warnOnce("look:" + k + "=" + p.getProperty(k), k + "=" + p.getProperty(k) + " is not 'Model/Size/walk|fly|fish' - that kind uses its built-in look until it is fixed"); continue; }
        looks.put(k.substring(5).trim().toLowerCase(), lv);
        continue;
      }
      if (k.startsWith("baby.") && k.length() > 5) {
        String[] bv = @PKG@.PetLook.parseBaby(p.getProperty(k), "/");
        if (bv == null) { @PKG@.PetsLog.warnOnce("baby:" + k + "=" + p.getProperty(k), k + "=" + p.getProperty(k) + " is not 'Model/Size' - that kind uses its built-in baby look until it is fixed"); continue; }
        babies.put(k.substring(5).trim().toLowerCase(), bv);
        continue;
      }
      if (k.startsWith("role.") && k.length() > 5) {
        String rv = @PKG@.PetKind.parseRoles(p.getProperty(k));
        if (rv == null) { @PKG@.PetsLog.warnOnce("role:" + k + "=" + p.getProperty(k), k + "=" + p.getProperty(k) + " is not gathering / combat / pet / fighter / mount (comma separated) - that kind uses its built-in roles until it is fixed"); continue; }
        roles.put(k.substring(5).trim().toLowerCase(), rv);
        continue;
      }
      if (!k.startsWith("kind.")) continue;
      inFile.add(k.substring(5).trim().toLowerCase());
      @PKG@.PetKind pk = @PKG@.PetKind.parse(k.substring(5), p.getProperty(k), "/");
      if (pk == null) { @PKG@.PetsLog.warnOnce("kind:" + k + "=" + p.getProperty(k), k + "=" + p.getProperty(k) + " is not 'Skill/Start rarity/Stats' with known stat keys - that kind is off until it is fixed"); continue; }
      ks.add(pk);
    }
  }
  // 0.2.3: a kind added in a later SkyyPets with no kind.<Kind> line in this file (written before it) = its built-in line
  for (int j = 0; j < @PKG@.PetKind.ADDED.length; j++) {
    int e = @PKG@.PetKind.ADDED[j].indexOf('=');
    String id = @PKG@.PetKind.ADDED[j].substring(0, e);
    if (inFile.contains(id.toLowerCase())) continue;
    @PKG@.PetKind ak = @PKG@.PetKind.parse(id, @PKG@.PetKind.ADDED[j].substring(e + 1), "/");
    if (ak == null) continue;
    ks.add(ak);
    ADDED_USED = ADDED_USED + 1;
    if (p != null && @PKG@.PetsLog.ONCE.putIfAbsent("added:" + id, Boolean.TRUE) == null) @PKG@.PetsLog.info("pet kind " + id + " (new in a later SkyyPets) has no line in config.properties - its built-in line is used (" + @PKG@.PetKind.ADDED[j].substring(e + 1) + "); Server Setup > Pets > Pet kinds can add a row to change it");
  }
  @PKG@.PetKind[] a = new @PKG@.PetKind[ks.size()];
  for (int i = 0; i < a.length; i++) a[i] = (@PKG@.PetKind) ks.get(i);
  KINDS = a;
  LOOKS = java.util.Collections.unmodifiableMap(looks);
  BABIES = java.util.Collections.unmodifiableMap(babies);
  ROLES = java.util.Collections.unmodifiableMap(roles);
}""")
M(cfgc, r"""
public static java.util.Properties props(String text) {
  java.util.Properties p = new java.util.Properties();
  try { p.load(new java.io.StringReader(text)); } catch (Throwable t) { }
  return p;
}""")
M(cfgc, r"""
public static java.util.Properties read(java.nio.file.Path f) {
  if (f == null) return null;
  java.io.InputStream in = null;
  try {
    if (!java.nio.file.Files.isRegularFile(f, new java.nio.file.LinkOption[0])) return null;
    in = java.nio.file.Files.newInputStream(f, new java.nio.file.OpenOption[0]);
    java.util.Properties p = new java.util.Properties();
    p.load(in);
    return p;
  } catch (Throwable t) {
    @PKG@.PetsLog.warn("could not read " + f + ": " + t + " - using the built-in defaults");
    return null;
  } finally {
    try { if (in != null) in.close(); } catch (Throwable t2) { }
  }
}""")
M(cfgc, r"""
public static void seed(java.nio.file.Path f) {
  if (f == null) return;
  try {
    if (java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) return;
    java.nio.file.Path dir = f.getParent();
    if (dir != null) java.nio.file.Files.createDirectories(dir, new java.nio.file.attribute.FileAttribute[0]);
    java.nio.file.Path tmp = f.resolveSibling(f.getFileName().toString() + ".tmp");
    java.nio.file.Files.write(tmp, DEFAULT_TEXT.getBytes("ISO-8859-1"), new java.nio.file.OpenOption[0]);
    java.nio.file.Files.move(tmp, f, new java.nio.file.CopyOption[] { java.nio.file.StandardCopyOption.REPLACE_EXISTING });
    @PKG@.PetsLog.info("wrote the default " + f.getFileName());
  } catch (Throwable t) { @PKG@.PetsLog.warn("could not write the default " + f + ": " + t); }
}""")
M(cfgc, r"""
public static void applyAll(java.util.Properties p) {
  java.util.Properties q = p != null ? p : props(DEFAULT_TEXT);
  applyScalars(q);
  applyTables(q);
  LOADS = LOADS + 1L;
}""")
