# ---- 0.4.0 the egg rows: "7000/2300/600/90/9/1" -> int[6] (null = not six whole numbers 0..1,000,000 with a sum above 0)
F(cfgc, "public static final String[] EGG_W_DEF = %s;" % jarr([EGG.rarity_text(EGG.RARITY_W[_r]) for _r in RARITIES]))
