M(cfgc, r"""
public static int[] eggW(String s) {
  if (s == null) return null;
  String t = s.trim().replace('|', '/').replace(',', '/');
  String[] p = t.split("/", -1);
  if (p.length != 6) return null;
  int[] w = new int[6];
  long sum = 0L;
  for (int i = 0; i < 6; i++) {
    try { w[i] = Integer.parseInt(p[i].trim()); } catch (Throwable x) { return null; }
    if (w[i] < 0 || w[i] > 1000000) return null;
    sum = sum + (long) w[i];
  }
  if (sum <= 0L) return null;
  return w;
}""")
