pm = cls("PetMath")
F(pm, "public static final int MAX_LEVEL = 100;")
# XP to go from level L-1 to L: lin (L-1) + cub (L-1)^3, rounded to 10 / 50 / 500 (Pets-Spec 3: 60, 240, 570, ... 45,000)
M(pm, r"""
public static long need(int level) {
  if (level <= 1) return 0L;
  double n = (double) (level - 1);
  double raw = @PKG@.PetsCfg.CURVE_LIN * n + @PKG@.PetsCfg.CURVE_CUB * n * n * n;
  if (Double.isNaN(raw) || raw < 1.0) return 1L;
  long step = raw < 1000.0 ? 10L : (raw < 10000.0 ? 50L : 500L);
  long r = Math.round(raw / (double) step) * step;
  return r < 1L ? 1L : r;
}""")
M(pm, r"""
public static int clampLevel(int l) {
  return l < 1 ? 1 : (l > MAX_LEVEL ? MAX_LEVEL : l);
}""")
# 0.3.0: the max level of a pet with `reb` pet rebirths: pets.level.cap + pets.rebirth.levels x reb (reb capped by pets.rebirth.max), 1-100
M(pm, r"""
public static int cap(int reb) {
  int mx = @PKG@.PetsCfg.REB_MAX < 0 ? 0 : @PKG@.PetsCfg.REB_MAX;
  int r = reb < 0 ? 0 : (reb > mx ? mx : reb);
  long c = (long) @PKG@.PetsCfg.LVL_CAP + (long) @PKG@.PetsCfg.REB_LEVELS * (long) r;
  return c < 1L ? 1 : (c > (long) MAX_LEVEL ? MAX_LEVEL : (int) c);
}""")
M(pm, "public static int maxCap() { return cap(@PKG@.PetsCfg.REB_MAX); }")
# the fewest pet rebirths whose max level holds `level` (the one-time update + /petadmin give); pets.rebirth.max when none does
M(pm, r"""
public static int implied(int level) {
  int mx = @PKG@.PetsCfg.REB_MAX < 0 ? 0 : @PKG@.PetsCfg.REB_MAX;
  for (int r = 0; r <= mx; r++) if (cap(r) >= level) return r;
  return mx;
}""")
M(pm, r"""
public static long total(int level) {
  long t = 0L;
  for (int l = 2; l <= clampLevel(level); l++) t = t + need(l);
  return t;
}""")

