M(rec, r"""
public synchronized java.util.Properties fuseApply(String base, String[] fd, int rar, int lvl, long xp, int reb) {
  java.util.Properties undo = new java.util.Properties();
  java.util.ArrayList ks = new java.util.ArrayList(this.p.stringPropertyNames());
  String bp = "pet." + base + ".";
  for (int i = 0; i < ks.size(); i++) {
    String k = (String) ks.get(i);
    boolean mine = k.startsWith(bp);
    for (int j = 0; !mine && j < fd.length; j++) if (k.startsWith("pet." + fd[j] + ".")) mine = true;
    if (mine) undo.setProperty(k, this.p.getProperty(k));
  }
  for (int j = 0; j < fd.length; j++) {
    String fp = "pet." + fd[j] + ".";
    for (int i = 0; i < ks.size(); i++) { String k = (String) ks.get(i); if (k.startsWith(fp)) this.p.remove(k); }
    this.frac.remove(fd[j]);
  }
  this.p.setProperty(bp + "rarity", String.valueOf(rar));
  this.p.setProperty(bp + "level", String.valueOf(@PKG@.PetMath.clampLevel(lvl)));
  this.p.setProperty(bp + "xp", String.valueOf(xp < 0L ? 0L : xp));
  if (reb > 0) this.p.setProperty(bp + "rebirth", String.valueOf(reb)); else this.p.remove(bp + "rebirth");
  this.frac.remove(base);
  touch();
  return undo;
}""")
