M(bf, r"""
public static double[] compute(@PKG@.PetRec r, String world) {
  double[] t = new double[N];
  if (!@PKG@.PetsCfg.ON || r == null || r.bad) return t;
  if (world != null && @PKG@.PetsCfg.listed(@PKG@.PetsCfg.NOBUFF, world)) return t;
  addPet(t, r, r.active(1), 100.0);
  addPet(t, r, slot2Pet(r), (double) @PKG@.PetsCfg.SLOT2_PCT);
  double cm = capMult(r);
  double fc = @PKG@.PetsCfg.FORT_CAP * cm;
  double sc = @PKG@.PetsCfg.SWING_CAP * cm;
  for (int i = 0; i < N; i++) {
    String k = @PKG@.PetKind.STAT_KEYS[i];
    if (k.startsWith("fortune.") && fc > 0.0 && t[i] > fc) t[i] = fc;     // 0.3.0 fixer: the caps x capMult; 0.4.8: 0 = no Fortune cap
    if (k.startsWith("swing.") && t[i] > sc) t[i] = sc;
  }
  return t;
}""")
