# =====================================================================================================================
# 0.2 PetFly: OUR fly-follow for flying + fish pets (pure maths; Skyy: "flying ones just fly around, they dont follow me")
# =====================================================================================================================
pfc = cls("PetFly")
M(pfc, r"""
public static double dist(double ax, double ay, double az, double bx, double by, double bz) {
  double dx = ax - bx; double dy = ay - by; double dz = az - bz;
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}""")
# the yaw (radians) that faces (dx, dz): yaw 0 faces -z (SkyyPetProbe PpLogic.yawToward)
M(pfc, r"""
public static float yaw(double dx, double dz) {
  if (dx == 0.0 && dz == 0.0) return 0.0f;
  return (float) Math.atan2(-dx, -dz);
}""")
M(pfc, r"""
public static double radius(int motion) {
  double r = @PKG@.PetsCfg.FOLLOW_DIST;
  return motion == 2 ? r * 0.8 : r;
}""")
M(pfc, r"""
public static double height(int motion, boolean joy) {
  double h = @PKG@.PetsCfg.FLY_HEIGHT;
  if (motion == 2) h = h * 0.7;
  return joy ? h + 0.6 : h;
}""")
M(pfc, r"""
public static double angSpeed(int motion, boolean joy) {
  double w = motion == 2 ? 0.5 : 0.8;
  return joy ? w * 4.0 : w;
}""")
M(pfc, r"""
public static double bob(int motion, double ph) {
  return Math.sin(ph) * (motion == 2 ? 0.15 : 0.25);
}""")
M(pfc, r"""
public static double[] orbit(double ox, double oy, double oz, double ang, double r, double h, double b) {
  return new double[] { ox + Math.cos(ang) * r, oy + h + b, oz + Math.sin(ang) * r };
}""")
# catch-up speed: faster the further behind (8 .. 30 blocks / s)
M(pfc, r"""
public static double speedFor(double d) {
  double v = 8.0 + d * 2.0;
  return v > 30.0 ? 30.0 : v;
}""")
# one smooth step from c toward t: a quarter of the way per 1/16 s, never faster than max blocks / s
M(pfc, r"""
public static double[] step(double cx, double cy, double cz, double tx, double ty, double tz, double dt, double max) {
  double dx = tx - cx; double dy = ty - cy; double dz = tz - cz;
  double d = Math.sqrt(dx * dx + dy * dy + dz * dz);
  if (d < 1.0E-6 || !(dt > 0.0)) return new double[] { cx, cy, cz };
  double k = dt * 4.0;
  if (k > 1.0) k = 1.0;
  double mv = d * k;
  double cap = max * dt;
  if (mv > cap) mv = cap;
  return new double[] { cx + dx / d * mv, cy + dy / d * mv, cz + dz / d * mv };
}""")
# a flying pet's teleport distance: the setting, but never inside its own circle (distance + height + 4)
M(pfc, r"""
public static double teleLimit(int motion) {
  double lim = (double) @PKG@.PetsCfg.TELE_DIST;
  double lo = radius(motion) + height(motion, true) + 4.0;
  return lim < lo ? lo : lim;
}""")
# one tick of one flying pet around the owner at (ox, oy, oz): { x, y, z, yaw, 1 = jump there (first sight / too far) }
M(pfc, r"""
public static double[] tick(@PKG@.PetView v, double ox, double oy, double oz, double dt, long now) {
  boolean joy = now < v.joy;
  if (dt > 0.25) dt = 0.25;
  if (dt < 0.0) dt = 0.0;
  v.ang = v.ang + angSpeed(v.motion, joy) * dt;
  if (v.ang > Math.PI * 2.0) v.ang = v.ang - Math.PI * 2.0;
  v.ph = v.ph + dt * (v.motion == 2 ? 1.6 : 2.4);
  if (v.ph > Math.PI * 2.0) v.ph = v.ph - Math.PI * 2.0;
  double[] t = orbit(ox, oy, oz, v.ang, radius(v.motion), height(v.motion, joy), bob(v.motion, v.ph));
  boolean jump = !v.hasPos;
  if (!jump) {
    if (dist(v.px, v.py, v.pz, ox, oy, oz) > teleLimit(v.motion)) { v.farT = v.farT + dt; if (v.farT >= 2.0) jump = true; }
    else v.farT = 0.0;
  }
  if (jump) {
    v.px = t[0]; v.py = t[1]; v.pz = t[2]; v.hasPos = true; v.farT = 0.0;
    return new double[] { t[0], t[1], t[2], (double) yaw(ox - t[0], oz - t[2]), 1.0 };
  }
  double[] n = step(v.px, v.py, v.pz, t[0], t[1], t[2], dt, speedFor(dist(v.px, v.py, v.pz, t[0], t[1], t[2])));
  double mx = n[0] - v.px; double mz = n[2] - v.pz;
  float y = (mx * mx + mz * mz) > 1.0E-6 ? yaw(mx, mz) : yaw(ox - n[0], oz - n[2]);
  v.px = n[0]; v.py = n[1]; v.pz = n[2];
  return new double[] { n[0], n[1], n[2], (double) y, 0.0 };
}""")

