# every second for a live creature: the name (level up), walking pets: the owner = the target, no debug flags, teleport when far
M(pvs, r"""
public static void upkeep(@PKG@.PetView v, @PKG@.PetRec r, @REF@ o, @CB@ cb, double[] op) {
  if (v.animEnd > 0L && System.currentTimeMillis() >= v.animEnd) { v.animEnd = 0L; @PKG@.PetWorld.stopAnim(cb, v.ref); ANIM_STOPS.incrementAndGet(); }
  if (r != null && !r.bad && r.has(v.petId)) {
    String pl = plateFor(r, v.petId, v.slot);
    if (!pl.equals(v.plate)) { v.plate = pl; @PKG@.PetWorld.plate(cb, v.ref, pl); }
  }
  if (v.slot == 2) aura(v, cb);
  pass(cb, v);
  if (v.motion != 0) return;
  @PKG@.PetWorld.clearDebug(cb, v.ref);
  @PKG@.PetWorld.mark(cb, v.ref, o);
  double[] pp = @PKG@.PetWorld.pos(cb, v.ref);
  if (pp == null || op == null) return;
  double d = @PKG@.PetFly.dist(pp[0], pp[1], pp[2], op[0], op[1], op[2]);
  if (d > (double) @PKG@.PetsCfg.TELE_DIST || Math.abs(pp[1] - op[1]) > 12.0) v.far = v.far + 1; else v.far = 0;
  if (v.far < 2) return;
  v.far = 0;
  double side = v.slot == 1 ? 1.4 : -1.4;
  @PKG@.PetWorld.teleport(cb, v.ref, op[0] + side, op[1], op[2] + 1.2, @PKG@.PetFly.yaw(-side, -1.2));
  TELEPORTS.incrementAndGet();
}""")
