# every tick: OUR fly-follow for the owner's flying / fish pets in this world
M(pvs, r"""
public static int steer(java.util.UUID u, @REF@ o, @CB@ cb, float dt) {
  if (u == null || o == null || OWN.isEmpty()) return 0;
  Object a = OWN.get(u);
  if (!(a instanceof Object[])) return 0;
  double[] op = null;
  int n = 0;
  long now = System.currentTimeMillis();
  for (int s = 1; s <= 2; s++) {
    Object x = ((Object[]) a)[s];
    if (!(x instanceof @PKG@.PetView)) continue;
    @PKG@.PetView v = (@PKG@.PetView) x;
    if (v.gone || v.motion == 0 || v.ref == null || !v.ref.isValid() || v.ref.getStore() != o.getStore()) continue;
    if (op == null) { op = @PKG@.PetWorld.pos(cb, o); if (op == null) return n; }
    double[] cur = @PKG@.PetWorld.pos(cb, v.ref);
    if (cur != null && v.hasPos) { v.px = cur[0]; v.py = cur[1]; v.pz = cur[2]; }
    double[] t = @PKG@.PetFly.tick(v, op[0], op[1], op[2], (double) dt, now);
    if (t[4] > 0.5 || "teleport".equals(@PKG@.PetsCfg.FLY_STEER)) @PKG@.PetWorld.teleport(cb, v.ref, t[0], t[1], t[2], (float) t[3]);
    else @PKG@.PetWorld.setPos(cb, v.ref, t[0], t[1], t[2], (float) t[3]);
    STEPS.incrementAndGet();
    n++;
  }
  return n;
}""")
