# THE GHOST SWEEP (P5: NonSerialized does not stop chunk saving): a pet creature LOADED from a chunk that is not the live tracked one
# (our role prefix, or a uuid we lost track of) is removed at once; the live one's chunk coming back re-attaches it. 0 = not ours.
M(pvs, r"""
public static int onLoad(@REF@ ref, @ADR@ why, @ST@ st, @CB@ cb) {
  if (why != @ADR@.LOAD || ref == null) return 0;
  java.util.UUID eu = @PKG@.PetWorld.uuid(st, ref);
  if (eu == null) return 0;
  String k = eu.toString();
  Object lo = LIVE.get(k);
  if (lo instanceof @PKG@.PetView && !((@PKG@.PetView) lo).gone) { ((@PKG@.PetView) lo).ref = ref; REATTACHED.incrementAndGet(); return 1; }
  String role = @PKG@.PetWorld.roleOf(st, ref);
  boolean ours = (role != null && role.startsWith(ROLE_PREFIX)) || DROPPED.containsKey(k) || lo != null;
  if (!ours && maybeOurs(role)) ours = ourTags(@PKG@.PetWorld.tags(st, ref));
  if (!ours) return 0;
  @PKG@.PetWorld.remove(cb, ref);
  DROPPED.remove(k);
  LIVE.remove(k);
  long n = SWEPT.incrementAndGet();
  if (n <= 20L || n % 100L == 0L) @PKG@.PetsLog.info("ghost sweep: removed a left-over pet creature (" + role + ", " + k + ") when its chunk loaded - " + n + " so far");
  return 2;
}""")
M(pvs, r"""
public static void onRemoved(@REF@ ref, @RR@ why, @ST@ st) {
  if (LIVE.isEmpty() || ref == null) return;
  java.util.UUID eu = @PKG@.PetWorld.uuid(st, ref);
  if (eu == null) return;
  Object lo = LIVE.get(eu.toString());
  if (!(lo instanceof @PKG@.PetView)) return;
  @PKG@.PetView v = (@PKG@.PetView) lo;
  if (v.gone || why == @RR@.UNLOAD) return;
  v.gone = true;
  v.why = "removed by the game (" + why + ")";
  unview(v);
  LIVE.remove(v.uuid);
  GONE_BY_GAME.incrementAndGet();
}""")
