# ONE ledger line per pet whose slot changed (the /pets page's "slot" lines; reason "loadout")
M(ops, r"""
public static void loadoutLedger(@PKG@.PetRec r, String id, String c1, String c2, String w1, String w2) {
  if (id == null || id.length() == 0 || !r.has(id)) return;
  int was = id.equals(c1) ? 1 : (id.equals(c2) ? 2 : 0);
  int now = id.equals(w1) ? 1 : (id.equals(w2) ? 2 : 0);
  if (was == now) return;
  @PKG@.PetStore.ledger(id, r.kindOf(id), r.rarityOf(id), r.levelOf(id), r.xpOf(id), slotName(was), slotName(now), "loadout", "SkyyWardrobe");
}""")
# both slots of the active profile from a loadout: '+' all / '=' one part skipped / '-' nothing changed (both skipped, or refused).
# The player's world thread (SkyyWardrobe); never touches items; no write when nothing changes.
M(ops, r"""
public static String loadoutSet(java.util.UUID u, String pet, String sum) {
  LOADOUT_SETS.incrementAndGet();
  if (u == null) return "-No player was named - your pets were not changed.";
  if (!@PKG@.PetsCfg.ON) return "-Pets are switched off on this server - your pets were not changed.";
  if (busy(u)) return "-Your profile is still switching - your pets were not changed. Try again in a moment.";
  if (@PKG@.PetStore.DIR == null) return "-SkyyPets is not ready yet - your pets were not changed.";
  @PKG@.PetRec r = @PKG@.PetStore.get(@PKG@.PetStore.pkey(u));
  if (r == null || r.bad) return "-Your pet file could not be read - an admin has been told. Your pets were not changed.";
  String p = pet == null ? "" : pet.trim();
  String q = sum == null ? "" : sum.trim();
  String c1 = r.active(1), c2 = r.active(2);
  String w1 = c1, w2 = c2;
  java.util.ArrayList skip = new java.util.ArrayList();
  if (p.length() == 0) w1 = "";
  else if (!r.has(p)) skip.add("pet slot " + p + " (gone)");
  else w1 = p;
  if (q.length() > 0 && !r.has(q)) skip.add("summon slot " + q + " (gone)");
  else if (!q.equals(c2) && !@PKG@.PetBuff.slot2Open(r)) skip.add("summon slot (locked: " + @PKG@.PetBuff.lockedWhy() + ")");
  else if (q.length() > 0 && !@PKG@.PetsCfg.summonable(r.kindOf(q))) skip.add("summon slot (" + summonWhy(r, q) + ")");
  else if (q.length() > 0 && q.equals(w1)) skip.add("summon slot (" + petName(r, q) + " is in the pet slot - one pet cannot be in both slots" + (q.equals(c2) ? "; the summon slot was emptied" : "") + ")");
  else w2 = q;
  if (w2.length() > 0 && w2.equals(w1)) w2 = "";
  boolean ch = !w1.equals(c1) || !w2.equals(c2);
  String now = "Pet slot: " + slotText(r, w1) + ", summon slot: " + slotText(r, w2) + ".";
  if (ch) {
    String o1 = r.get("active.1"), o2 = r.get("active.2");
    r.set("active.1", w1);
    r.set("active.2", w2);
    if (!@PKG@.PetStore.save(r)) {
      r.set("active.1", o1);
      r.set("active.2", o2);
      return "-Your pets could not be saved - nothing was changed. Try again in a moment.";
    }
    LOADOUT_WRITES.incrementAndGet();
    java.util.ArrayList seen = new java.util.ArrayList();
    String[] ids = new String[] { c1, c2, w1, w2 };
    for (int i = 0; i < ids.length; i++) {
      if (ids[i].length() == 0 || seen.contains(ids[i])) continue;
      seen.add(ids[i]);
      loadoutLedger(r, ids[i], c1, c2, w1, w2);
    }
  }
  if (skip.size() == 0) return "+" + now;
  StringBuilder sk = new StringBuilder();
  for (int i = 0; i < skip.size(); i++) { if (i > 0) sk.append("; "); sk.append((String) skip.get(i)); }
  if (skip.size() >= 2 && !ch) return "-Nothing changed. Skipped: " + sk.toString() + ".";
  return "=" + now + " Skipped: " + sk.toString() + ".";
}""")
M(ops, r"""
public static String line(@PKG@.PetRec r, String id) {
  int s = r.slotOf(id);
  return id + "  " + petName(r, id) + "  Lv " + r.levelOf(id) + " / " + r.capOf(id) + (r.rebirthOf(id) > 0 ? " R" + r.rebirthOf(id) : "") + " (" + @PKG@.PetsLog.grp(r.xpOf(id)) + " / " + @PKG@.PetsLog.grp(@PKG@.PetMath.need(r.levelOf(id) + 1)) + " XP)" + (s > 0 ? "  [" + slotName(s) + "]" : "");
}""")
# /petadmin <verb> [args]: the target must be online (its active profile)
M(ops, r"""
public static String admin(String by, String verb, String player, String a, String b, String c) {
  String v = verb == null ? "" : verb.trim().toLowerCase();
  if (v.length() == 0 || v.equals("help")) return "=/petadmin give <player> <kind> [rarity] [level] | take <player> <id> | unlock <player> | lock <player> | list <player> | restore <player> <id> [force] | xp <player> <skill> <amount> | egg <player> <category> <rarity> [n] | hatchodds <category> <rarity> [n] | kinds | sweep";
  if (v.equals("sweep")) return "=" + @PKG@.PetViews.status();
  if (v.equals("kinds")) {
    StringBuilder sb = new StringBuilder();
    sb.append("Pet kinds: " + @PKG@.PetsCfg.kindList() + "\nRarities: Common, Uncommon, Rare, Epic, Legendary\nStat keys: ");
    for (int i = 0; i < @PKG@.PetKind.STAT_KEYS.length; i++) sb.append(i > 0 ? ", " : "").append(@PKG@.PetKind.STAT_KEYS[i]);
    sb.append("\nBuilt-in pet looks (model size motion; a Server Setup > Pets > Pet looks row wins): " + @PKG@.PetLook.builtIn(@PKG@.PetLook.LOOK_DEF));
    sb.append("\nBuilt-in baby looks (model size; Baby looks row wins): " + @PKG@.PetLook.builtIn(@PKG@.PetLook.BABY_DEF));
    sb.append("\nBuilt-in pet roles (a Server Setup > Pets > Pet roles row wins; only fighter / mount kinds can be summoned): " + @PKG@.PetLook.builtIn(@PKG@.PetKind.ROLE_DEF));
    return "=" + sb.toString();
  }
  if (!v.equals("give") && !v.equals("take") && !v.equals("unlock") && !v.equals("lock") && !v.equals("list") && !v.equals("restore") && !v.equals("xp"))
    return "-Unknown option " + verb + ". /petadmin help";
  if (player == null || player.trim().length() == 0) return "-Which player? /petadmin " + v + " <player> ...";
  java.util.UUID u = @PKG@.PetsEng.byName(player);
  if (u == null) return "-" + player + " is not online (pets live in the active profile of an online player).";
  String nm = @PKG@.PetsEng.nameOf(u);
  @PKG@.PetRec r = @PKG@.PetStore.get(@PKG@.PetStore.pkey(u));
  if (v.equals("list")) {
    if (r.bad) return "-" + nm + "'s pet file (" + r.key + ") could not be read: " + r.why;
    String[] ids = r.ids();
    StringBuilder sb = new StringBuilder();
    sb.append(nm + " (" + r.key + "): " + ids.length + " pets, summon slot " + (@PKG@.PetBuff.slot2Open(r) ? "open" : "locked"));
    for (int i = 0; i < ids.length && i < 40; i++) sb.append("\n").append(line(r, ids[i]));
    if (ids.length > 40) sb.append("\n... and " + (ids.length - 40) + " more");
    return "=" + sb.toString();
  }
  if (r.bad) return "-" + nm + "'s pet file could not be read (" + r.why + ") - nothing was changed.";
  if (v.equals("unlock") || v.equals("lock")) {
    boolean on = v.equals("unlock");
    if (r.unlocked() == on) return "=" + nm + "'s summon slot is already " + (on ? "unlocked." : "locked.");
    r.set("slot2.unlocked", on ? "true" : "false");
    if (!@PKG@.PetStore.save(r)) return "-Could not save " + nm + "'s pets - nothing changed.";
    @PKG@.PetStore.ledger("-", "-", 0, 0, 0L, "", r.key, on ? "unlock slot 2" : "lock slot 2", by);
    if (on) @PKG@.PetsEng.tell(u, "[Pets] Your summon slot is unlocked! A pet there gives " + @PKG@.PetsCfg.SLOT2_PCT + "% of its buffs - /pets.", "@COLGLD@");
    return "+" + nm + "'s summon slot is now " + (on ? "unlocked" : "locked") + (on && "off".equals(@PKG@.PetsCfg.SLOT2_MODE) ? " (but Server Setup has the summon slot closed for everyone)." : ".");
  }
  if (v.equals("give")) {
    if (a == null || a.trim().length() == 0) return "-Which kind? /petadmin kinds";
    @PKG@.PetKind pk = @PKG@.PetsCfg.kind(a);
    if (pk == null) return "-No pet kind " + a + ". /petadmin kinds";
    if (!@PKG@.PetsCfg.kindOn(pk.id)) return "-" + pk.name + " is switched off (Server Setup > Pets > Pet kinds switched off).";
    int rar = b == null || b.trim().length() == 0 ? pk.rarity : @PKG@.PetKind.rarityOf(b);
    if (rar < 1 || rar > 5) return "-Rarity is Common, Uncommon, Rare, Epic or Legendary (1-5). Mythic comes from eggs.";
    int lvl = 1;
    if (c != null && c.trim().length() > 0) { try { lvl = Integer.parseInt(c.trim()); } catch (Throwable t) { lvl = -1; } }
    int mc = @PKG@.PetMath.maxCap();
    if (lvl < 1 || lvl > mc) return "-Level is 1-" + mc + ".";
    int rb = @PKG@.PetMath.implied(lvl);
    String res = createR(r, null, pk.id, rar, lvl, 0L, rb, "admin", by, true);
    if (res.startsWith("-")) return res;
    @PKG@.PetsEng.tell(u, "[Pets] You got a new pet: " + @PKG@.PetKind.rarityName(rar) + " " + pk.name + " (Lv " + lvl + ")! Open /pets.", "@COLGLD@");
    return "+Gave " + nm + " a " + @PKG@.PetKind.rarityName(rar) + " " + pk.name + " Lv " + lvl + (rb > 0 ? " with " + rb + " pet rebirths (that level needs them)" : "") + " (id " + res + (r.slotOf(res) == 1 ? ", in the pet slot" : "") + ").";
  }
  if (v.equals("take")) {
    if (a == null || !r.has(a.trim())) return "-" + nm + " has no pet " + a + ". /petadmin list " + nm;
    String id = a.trim();
    String kd = r.kindOf(id);
    int rar = r.rarityOf(id), lvl = r.levelOf(id), rbt = r.rebirthOf(id);
    long x = r.xpOf(id);
    int was = r.slotOf(id);
    String pn = petName(r, id);
    java.util.Properties gone = r.remove(id);
    if (!@PKG@.PetStore.save(r)) {
      java.util.Iterator it = gone.stringPropertyNames().iterator();
      while (it.hasNext()) { String k = (String) it.next(); r.set(k, gone.getProperty(k)); }
      if (was > 0) r.set("active." + was, id);
      return "-Could not save " + nm + "'s pets - nothing was taken.";
    }
    @PKG@.PetStore.INDEX.remove(id, r.key);
    @PKG@.PetStore.ledgerR(id, kd, rar, lvl, x, r.key, "", "take", by, rbt);
    @PKG@.PetsEng.tell(u, "[Pets] An admin took your " + pn + ".", "@COLINF@");
    return "+Took " + nm + "'s " + pn + " (" + id + "). Undo: /petadmin restore " + nm + " " + id;
  }
  if (v.equals("restore")) {
    if (a == null || a.trim().length() == 0) return "-Which pet id? (ledger.log)";
    String id = a.trim().toLowerCase();
    if (!id.matches("[0-9a-z]{8}")) return "-" + a.trim() + " is not a pet id (8 letters / digits, see /petadmin list or ledger.log).";
    Object owner = @PKG@.PetStore.INDEX.get(id);
    if (owner != null) return "-Pet " + id + " still belongs to " + owner + " - nothing to restore.";
    if (!@PKG@.PetStore.BAD.isEmpty()) {
      Object[] bk = @PKG@.PetStore.BAD.keySet().toArray();
      StringBuilder bs = new StringBuilder();
      for (int i = 0; i < bk.length && i < 5; i++) bs.append(i > 0 ? ", " : "").append(String.valueOf(bk[i]));
      if (bk.length > 5) bs.append(" and " + (bk.length - 5) + " more");
      return "-Not now: " + bk.length + " pet file(s) could not be read (" + bs.toString() + ") and may still hold pet " + id + ". Fix or move those files first (a fixed file is read again when its player joins), then restore.";
    }
    String[] l = @PKG@.PetStore.ledgerFind(id);
    if (l == null) return "-Pet " + id + " is not in ledger.log.";
    boolean force = b != null && b.trim().equalsIgnoreCase("force");
    if (l[8].startsWith("fuse-take") && !force) return "-Pet " + id + " was used up in a fuse (" + l[8] + ") - its rarity lives on in the fused pet. Add force to bring it back anyway: /petadmin restore " + nm + " " + id + " force";
    if (@PKG@.PetsCfg.kind(l[2]) == null) return "-Pet " + id + " was a " + l[2] + ", and that pet kind does not exist any more (Server Setup > Pets > Pet kinds).";
    int rar = 1, lvl = 1;
    long x = 0L;
    try { rar = Integer.parseInt(l[3]); lvl = Integer.parseInt(l[4]); x = Long.parseLong(l[5]); } catch (Throwable t) { }
    if (rar < 1 || rar > 6) rar = 1;
    int rb = -1;
    if (l.length > 10) { try { rb = Integer.parseInt(l[10].trim()); } catch (Throwable t2) { rb = -1; } }
    if (rb < 0) rb = @PKG@.PetMath.implied(lvl);
    String res = createR(r, id, l[2], rar, lvl, x, rb, force ? "restore (force)" : "restore", by, false);
    if (res.startsWith("-")) return res;
    @PKG@.PetsEng.tell(u, "[Pets] An admin gave back your " + petName(r, id) + ".", "@COLGLD@");
    return "+Restored " + petName(r, id) + " Lv " + r.levelOf(id) + " (" + id + ") to " + nm + ".";
  }
  if (a == null || a.trim().length() == 0 || b == null) return "-Use /petadmin xp <player> <skill> <amount>.";
  long n = 0L;
  try { n = Long.parseLong(b.trim()); } catch (Throwable t) { n = -1L; }
  if (n <= 0L || n > 100000000L) return "-Amount is 1 - 100,000,000.";
  if (@PKG@.PetStore.REC.get(r.key) == null) @PKG@.PetStore.REC.put(r.key, r);
  int got = @PKG@.PetXp.give2(u, a.trim(), n, false);   // 0.4.7: the amount as typed (no P3 divisor; the pace still counts)
  if (got == 0) return "=No slotted pet of " + nm + " got XP (empty slots, kinds off, or pets off).";
  return "+" + got + " slotted pet(s) of " + nm + " got " + a.trim() + " XP from " + @PKG@.PetsLog.grp(n) + ".";
}""")

# ---------------------------------------------------------------------------------------------------------------- 0.3.0 the pet system
F(ops, "public static final String[] START_TYPES = new String[] { \"Mining\", \"Farming\", \"Foraging\", \"Combat\" };")
