# the category's kinds that can hatch, BEST FIRST: the order row (unknown / switched-off kinds left out), then the kinds of that skill no
# list names, each before the first listed kind of a lower start rarity (logged once). "-" = no pets for that egg.
M(egg, r"""
public static String[] order(String cat) {
  java.util.ArrayList out = new java.util.ArrayList();
  if (cat == null) return new String[0];
  String row = @PKG@.PetsCfg.eggOrder(cat);
  if (row != null && row.trim().equals("-")) return new String[0];
  if (row != null) {
    String[] a = row.split(",");
    for (int i = 0; i < a.length; i++) {
      String k = a[i].trim();
      if (k.length() == 0) continue;
      @PKG@.PetKind pk = @PKG@.PetsCfg.kind(k);
      if (pk == null) { @PKG@.PetsLog.warnOnce("eggorder:" + cat + ":" + k, "pets.egg.order." + cat.toLowerCase() + " names " + k + ", which is not a pet kind - it is left out"); continue; }
      if (!@PKG@.PetsCfg.kindOn(pk.id) || out.contains(pk.id)) continue;
      out.add(pk.id);
    }
  }
  @PKG@.PetKind[] ks = @PKG@.PetsCfg.KINDS;
  for (int i = 0; i < ks.length; i++) {
    @PKG@.PetKind pk = ks[i];
    if (!pk.skill.equalsIgnoreCase(cat) || out.contains(pk.id) || !@PKG@.PetsCfg.kindOn(pk.id) || listedAnywhere(pk.id)) continue;
    int at = out.size();
    for (int j = 0; j < out.size(); j++) {
      @PKG@.PetKind q = @PKG@.PetsCfg.kind((String) out.get(j));
      if (q != null && q.rarity < pk.rarity) { at = j; break; }
    }
    out.add(at, pk.id);
    if (@PKG@.PetsLog.ONCE.putIfAbsent("eggplace:" + pk.id, Boolean.TRUE) == null) @PKG@.PetsLog.info("pet kind " + pk.id + " is in no egg list - " + cat + " eggs place it by its start rarity (Server Setup > Pets > Pet eggs can list it)");
  }
  String[] o = new String[out.size()];
  for (int i = 0; i < o.length; i++) o[i] = (String) out.get(i);
  return o;
}""")
# weight per pet, BEST FIRST: the pool = all or the best half (min 1); inside it R ^ -x, x = 0 for the pool's worst, 1 for its best
M(egg, r"""
public static double[] weights(int n, double ratio, boolean half) {
  double[] w = new double[n < 0 ? 0 : n];
  if (n <= 0) return w;
  int m = half ? (n / 2 < 1 ? 1 : n / 2) : n;
  double r = ratio > 0.0 ? ratio : 1.0;
  for (int i = 0; i < m; i++) {
    double x = m == 1 ? 1.0 : (double) (m - 1 - i) / (double) (m - 1);
    w[i] = Math.pow(r, -x);
  }
  return w;
}""")
M(egg, r"""
public static int pick(java.util.Random r, double[] w) {
  double t = 0.0;
  for (int i = 0; i < w.length; i++) if (w[i] > 0.0) t = t + w[i];
  if (!(t > 0.0)) return -1;
  double x = r.nextDouble() * t;
  int last = -1;
  for (int i = 0; i < w.length; i++) {
    if (!(w[i] > 0.0)) continue;
    last = i;
    x = x - w[i];
    if (x < 0.0) return i;
  }
  return last;
}""")
M(egg, r"""
public static int pickW(java.util.Random r, int[] w) {
  double[] d = new double[w.length];
  for (int i = 0; i < w.length; i++) d[i] = (double) w[i];
  return pick(r, d);
}""")
M(egg, r"""
public static double[] catWeights(String[] o, int erar) {
  return weights(o.length, @PKG@.PetsCfg.eggRatio(erar), @PKG@.PetsCfg.eggHalf(erar));
}""")
