# the hatch page's odds lines: "Goat 3.9% - Warthog 9.7% - ..." (this egg's own weights) + the rarity line
M(egg, r"""
public static String oddsText(String cat, int erar) {
  String[] o = order(cat);
  if (o.length == 0) return "No pet can hatch from this egg on this server right now.";
  double[] w = catWeights(o, erar);
  double t = 0.0;
  for (int i = 0; i < w.length; i++) t = t + w[i];
  StringBuilder b = new StringBuilder();
  for (int i = 0; i < o.length; i++) {
    if (!(w[i] > 0.0)) continue;
    if (b.length() > 0) b.append(" - ");
    b.append(kindName(o[i])).append(' ').append(pct(100.0 * w[i] / t));
  }
  int left = 0;
  for (int i = 0; i < o.length; i++) if (!(w[i] > 0.0)) left++;
  if (left > 0) b.append(" (the other " + left + " never hatch from this egg)");
  return b.toString();
}""")
M(egg, r"""
public static String rarityText(int erar) {
  int[] w = @PKG@.PetsCfg.eggRarity(erar);
  long t = 0L;
  for (int i = 0; i < w.length; i++) t = t + (long) w[i];
  StringBuilder b = new StringBuilder();
  for (int i = 0; i < w.length; i++) {
    if (w[i] <= 0) continue;
    if (b.length() > 0) b.append(" - ");
    b.append(@PKG@.PetKind.rarityName(i + 1)).append(' ').append(pct(100.0 * (double) w[i] / (double) t));
  }
  return b.toString();
}""")
