# THE HATCH (the caller holds the record's io lock + its monitor, on the world thread). Steps: 1 the journal line, 2 the egg out of its slot
# (exactly one, counted), 3 the debt + reveal lines, 4 ONE atomic save of the record with the new pet (createR: the rename is the commit),
# 5 hatch-done. A save that fails puts the egg back. Returns { result, hid, pet id, kind, Integer rarity }.
M(egg, r"""
public static Object[] hatchLocked(java.util.UUID u, @PKG@.PetRec r, @PKG@.PetInv inv, String eggId, int slot, int ci, int erar, String by) {
  java.util.Random rn = rnd();
  String cat = @PKG@.PetEggDefs.CATS[ci];
  String kind = roll1(rn, cat, erar);
  if (kind == null) return res("-No " + cat + " pet can hatch on this server right now - your egg is kept.");
  int prar = roll2(rn, erar);
  String hid = @PKG@.PetStore.newId();
  if (hid == null) return res("-No free hatch id - try again.");
  int before = inv.count(eggId);
  led(r, "hatch-intent " + hid + " egg=" + eggId + " slot=" + slot + " before=" + before + " kind=" + kind + " rarity=" + prar, by);
  step(1);
  int took = inv.takeOne(slot, eggId);
  if (took != 1) {
    int back = took > 0 ? inv.give(eggId, took) : 0;
    led(r, "hatch-abort " + hid + " take (" + took + " eggs left the slot, " + back + " put back - nothing hatched)", by);
    ABORTS.incrementAndGet();
    if (took > back) @PKG@.PetsLog.warn("hatch " + hid + " of " + r.key + ": " + took + " eggs left the slot but only " + back + " could be put back (" + eggId + ")");
    return res("-Your egg could not be taken - nothing hatched. Try again.");
  }
  step(2);
  long now = System.currentTimeMillis();
  r.set("eggdebt." + hid, eggId + "|" + before + "|" + now + "|" + (before - 1));     // egg | count before | ms | count right after the take
  r.set("hatch.unseen." + hid, eggId + "|" + kind + "|" + prar);
  step(3);
  String pid = @PKG@.PetOps.createR(r, null, kind, prar, 1, 0L, 0, "egg:" + eggId + ":" + hid, by, true);
  if (pid.startsWith("-")) {
    r.set("eggdebt." + hid, null);
    r.set("hatch.unseen." + hid, null);
    int back = inv.give(eggId, 1);
    led(r, "hatch-abort " + hid + (back == 1 ? " save-refund (the pet file could not be saved - the egg is back)" : " refund-failed (the pet file could not be saved AND the egg could not be put back: give " + eggId + " x1)"), by);
    ABORTS.incrementAndGet();
    if (back != 1) @PKG@.PetsLog.warn("hatch " + hid + " of " + r.key + ": nothing hatched and the egg " + eggId + " could not be put back - give it back by hand (/petadmin egg)");
    return res(back == 1 ? "-Your pets could not be saved - nothing hatched, your egg is back." : "-Your pets could not be saved and your egg could not be put back - an admin has been told (hatch " + hid + ").");
  }
  step(4);
  SESSION.put(hid, Long.valueOf(now));
  led(r, "hatch-done " + hid + " " + pid + " " + kind + " " + @PKG@.PetKind.rarityName(prar), by);
  step(5);
  HATCHES.incrementAndGet();
  return new Object[] { "+You hatched a " + @PKG@.PetKind.rarityName(prar) + " " + kindName(kind) + "!", hid, pid, kind, Integer.valueOf(prar) };
}""")
M(egg, r"""
public static Object[] hatchSync(java.util.UUID u, @PKG@.PetRec r, @PKG@.PetInv inv, String eggId, int slot, int ci, int erar, String by) {
  Object[] res = null;
  synchronized (r) { res = hatchLocked(u, r, inv, eggId, slot, ci, erar, by); }
  return res;
}""")
