# ---- STARTUP (after scanAll): a hatch-intent with no hatch-done / hatch-abort = the server stopped in the middle. The pet files decide:
# that hatch's debt line or a pet with src egg:<egg>:<hid> = the save went through (hatch-done); none = hatch-abort crash (no pet; the
# player file was never saved without the egg). Only ledger lines are written. { open, done, aborted }
M(egg, r"""
public static int[] recover() {
  int open = 0, dn = 0, ab = 0;
  java.nio.file.Path root = @PKG@.PetStore.ROOT;
  if (root == null) return new int[] { 0, 0, 0 };
  try {
    java.nio.file.Path f = root.resolve("ledger.log");
    if (!java.nio.file.Files.isRegularFile(f, new java.nio.file.LinkOption[0])) return new int[] { 0, 0, 0 };
    java.util.List ls = java.nio.file.Files.readAllLines(f, java.nio.charset.StandardCharsets.UTF_8);
    java.util.LinkedHashMap intents = new java.util.LinkedHashMap();
    java.util.HashSet closed = new java.util.HashSet();
    for (int i = 0; i < ls.size(); i++) {
      String[] p = ((String) ls.get(i)).split("\t", -1);
      if (p.length < 10) continue;
      String[] w = p[8].split(" ");
      if (w.length < 2) continue;
      if (w[0].equals("hatch-intent")) intents.put(w[1], p);
      else if (w[0].equals("hatch-done") || w[0].equals("hatch-abort")) closed.add(w[1]);
    }
    java.util.ArrayList todo = new java.util.ArrayList();
    java.util.Iterator it = intents.keySet().iterator();
    while (it.hasNext()) { String h = (String) it.next(); if (!closed.contains(h)) todo.add(h); }
    if (todo.isEmpty()) return new int[] { 0, 0, 0 };
    java.util.HashMap found = new java.util.HashMap();
    java.nio.file.Path dir = @PKG@.PetStore.DIR;
    if (dir != null && java.nio.file.Files.isDirectory(dir, new java.nio.file.LinkOption[0])) {
      java.nio.file.DirectoryStream ds = java.nio.file.Files.newDirectoryStream(dir, "*.properties");
      try {
        java.util.Iterator di = ds.iterator();
        while (di.hasNext()) {
          String n = ((java.nio.file.Path) di.next()).getFileName().toString();
          String key = n.substring(0, n.length() - ".properties".length());
          if (!@PKG@.PetStore.keyOk(key)) continue;
          @PKG@.PetRec r = @PKG@.PetStore.load(key);
          if (r.bad) continue;
          java.util.Iterator ki = r.p.stringPropertyNames().iterator();
          while (ki.hasNext()) {
            String pk = (String) ki.next();
            if (pk.startsWith("eggdebt.")) found.put(pk.substring(8), key);
            else if (pk.startsWith("pet.") && pk.endsWith(".src")) {
              String v = r.p.getProperty(pk, "");
              if (v.startsWith("egg:") && v.lastIndexOf(':') > 4) found.put(v.substring(v.lastIndexOf(':') + 1), key);
            }
          }
        }
      } finally { ds.close(); }
    }
    for (int i = 0; i < todo.size(); i++) {
      String h = (String) todo.get(i);
      String[] p = (String[]) intents.get(h);
      open++;
      if (found.containsKey(h)) {
        @PKG@.PetStore.ledgerR("-", "-", 0, 0, 0L, p[6], p[7], "hatch-done " + h + " (recovered at startup: the pet was saved before the stop)", "startup", -1);
        dn++;
        @PKG@.PetsLog.info("hatch " + h + " of " + found.get(h) + " was saved but its last ledger line was missing - hatch-done written (an egg that came back is taken at the next join)");
      } else {
        @PKG@.PetStore.ledgerR("-", "-", 0, 0, 0L, p[6], p[7], "hatch-abort " + h + " crash (the server stopped before the pet was saved - no pet; the player was never saved without the egg)", "startup", -1);
        ab++;
        @PKG@.PetsLog.warn("hatch " + h + " was cut off before its save - nothing hatched, the egg stays (ledger hatch-abort)");
      }
    }
  } catch (Throwable t) { @PKG@.PetsLog.warn("could not check ledger.log for cut-off hatches: " + t); }
  return new int[] { open, dn, ab };
}""")
