M(hy, r"""
public static int[] recover() {
  int open = 0, dn = 0, ab = 0;
  java.nio.file.Path root = @PKG@.PetStore.ROOT;
  if (root == null) return new int[] { 0, 0, 0 };
  try {
    java.nio.file.Path f = root.resolve("ledger.log");
    if (!java.nio.file.Files.isRegularFile(f, new java.nio.file.LinkOption[0])) return new int[] { 0, 0, 0 };
    java.util.List ls = java.nio.file.Files.readAllLines(f, java.nio.charset.StandardCharsets.UTF_8);
    java.util.LinkedHashMap intents = new java.util.LinkedHashMap();
    java.util.HashSet closed = new java.util.HashSet();
    for (int i = 0; i < ls.size(); i++) {
      String[] p = ((String) ls.get(i)).split("\t", -1);
      if (p.length < 10) continue;
      String[] w = p[8].split(" ");
      if (w.length < 2) continue;
      if (w[0].equals("egg-place-intent") || w[0].equals("egg-remove-intent")) intents.put(w[1], p);
      else if (w[0].equals("egg-place-done") || w[0].equals("egg-place-abort") || w[0].equals("egg-remove-done") || w[0].equals("egg-remove-abort")) closed.add(w[1]);
    }
    java.util.ArrayList todo = new java.util.ArrayList();
    java.util.Iterator it = intents.keySet().iterator();
    while (it.hasNext()) { String h = (String) it.next(); if (!closed.contains(h)) todo.add(h); }
    if (todo.isEmpty()) return new int[] { 0, 0, 0 };
    java.util.HashSet found = new java.util.HashSet();
    java.nio.file.Path dir = @PKG@.PetStore.DIR;
    if (dir != null && java.nio.file.Files.isDirectory(dir, new java.nio.file.LinkOption[0])) {
      java.nio.file.DirectoryStream ds = java.nio.file.Files.newDirectoryStream(dir, "*.properties");
      try {
        java.util.Iterator di = ds.iterator();
        while (di.hasNext()) {
          String nmf = ((java.nio.file.Path) di.next()).getFileName().toString();
          String key = nmf.substring(0, nmf.length() - ".properties".length());
          if (!@PKG@.PetStore.keyOk(key)) continue;
          @PKG@.PetRec r = @PKG@.PetStore.load(key);
          if (r.bad) continue;
          java.util.Iterator ki = r.p.stringPropertyNames().iterator();
          while (ki.hasNext()) {
            String pk = (String) ki.next();
            if (pk.startsWith("eggdebt.")) found.add(pk.substring(8));
            else if (pk.startsWith("eggcredit.")) found.add(pk.substring(10));
            else if (pk.startsWith("hatchery.")) {
              String[] q = r.p.getProperty(pk, "").split("\\|", -1);
              if (q.length >= 3) found.add(q[2]);
            }
          }
        }
      } finally { ds.close(); }
    }
    for (int i = 0; i < todo.size(); i++) {
      String h = (String) todo.get(i);
      String[] p = (String[]) intents.get(h);
      boolean pl = p[8].startsWith("egg-place-intent");
      open++;
      if (found.contains(h)) {
        @PKG@.PetStore.ledgerR("-", "-", 0, 0, 0L, p[6], p[7], (pl ? "egg-place-done " : "egg-remove-done ") + h + " (recovered at startup: the pet file was saved before the stop)", "startup", -1);
        dn++;
      } else {
        // critic fix 2: the pet file was not saved - but the player file may have been (an autosave in between): eggcheck.<hid> lets the next
        // join compare the real inventory / Void with the count the intent wrote
        String[] w = p[8].split(" ");
        String eg = "", bf = "0", sr = "inv", pd = "-";
        for (int j = 2; j < w.length; j++) {
          if (w[j].startsWith("egg=")) eg = w[j].substring(4);
          else if (w[j].startsWith("before=")) bf = w[j].substring(7);
          else if (w[j].startsWith("src=")) sr = w[j].substring(4);
          else if (w[j].startsWith("placed=")) pd = w[j].substring(7);
        }
        boolean chk = false;
        try {
          if (@PKG@.PetStore.keyOk(p[7]) && @PKG@.PetEggDefs.index(eg) >= 0) {
            @PKG@.PetRec cr = @PKG@.PetStore.get(p[7]);
            if (!cr.bad) { cr.set("eggcheck." + h, eg + "|" + bf + "|" + (pl ? "place" : "remove") + "|" + sr + "|" + pd); chk = @PKG@.PetStore.save(cr); }
          }
        } catch (Throwable tc) { @PKG@.PetsLog.warn("could not note the check of cut-off Hatchery move " + h + ": " + tc); }
        @PKG@.PetStore.ledgerR("-", "-", 0, 0, 0L, p[6], p[7], (pl ? "egg-place-abort " : "egg-remove-abort ") + h + " crash (the server stopped before the pet file was saved; " + (chk ? "the next join checks the inventory against the count before" : "NO CHECK NOTED") + ")", "startup", -1);
        ab++;
        @PKG@.PetsLog.warn("hatchery " + (pl ? "place " : "take-out ") + h + " was cut off before its save - the pet file is unchanged" + (chk ? "; the player's inventory is checked at the next join" : " and the check could not be noted - look at " + p[7] + " by hand"));
      }
    }
  } catch (Throwable t) { @PKG@.PetsLog.warn("could not check ledger.log for cut-off Hatchery moves: " + t); }
  return new int[] { open, dn, ab };
}""")
