# ---- the egg's right-click (OpenCustomUI SkyyPetsHatch): ONE chat line, nothing opens, nothing is consumed (Skyy: "hatchery only")
M(hy, r"""
public static Object rightClick(Object o) {
  try {
    if (!(o instanceof @PR@)) return null;
    @PR@ pr = (@PR@) o;
    java.util.UUID u = pr.getUuid();
    long now = System.currentTimeMillis();
    Object l = u == null ? null : RCLICK.get(u);
    RIGHT.incrementAndGet();
    if (l instanceof Long && now - ((Long) l).longValue() >= 0L && now - ((Long) l).longValue() < 1500L) return null;
    if (u != null) RCLICK.put(u, Long.valueOf(now));
    @PKG@.PetsEng.say(pr, "[Pets] Hatch eggs in the Hatchery: /pets", "@COLINF@");
  } catch (Throwable t) { @PKG@.PetsLog.warnOnce("rightclick:" + t.getClass().getName(), "the egg right-click line failed: " + t); }
  return null;
}""")

