PV_ALT = []          # the other look of every choose() (checked for proven properties; the previews hold the first look)


def jl(parent, mkup, root=True):
    if PV_KEY[0] is not None:
        PV[PV_KEY[0]].append((parent, mkup.a if isinstance(mkup, SUI.Choice) else mkup))
        if isinstance(mkup, SUI.Choice):
            PV_ALT.append(mkup.b)
    return SUI.java_append(parent, mkup, page_root=root)


def apj(ap):
    """ap.java for a page part, recorded in the current preview"""
    if PV_KEY[0] is not None:
        PV[PV_KEY[0]].extend(ap)
    return ap.java("b", page_root=False)


def jsets(mkup):
    return "\n".join(SUI.java_set(i, p, v) for i, p, v in getattr(mkup, "sets", []))


def _tog(ident, text, w, sel, left):
    return SUI.button(ident, text, "tertiary", "small", w=w, selected=sel, anchor={"left": left} if left else None)


def _toggles(row, prefix, texts, widths, var, first_left=0):
    out = []
    for i in range(len(texts)):
        left = first_left if i == 0 else TGAP
        out.append(jl(row, SUI.choose(J_("%s%d" % (var, i)), _tog("%s%d" % (prefix, i), texts[i], widths[i], True, left),
                                      _tog("%s%d" % (prefix, i), texts[i], widths[i], False, left)), False))
    return "\n".join(out)


