M(PAGEC, r"""
public String act(java.util.UUID u, String id, String by, @ST@ st, @REF@ ref) {
  @PKG@.PetRec r = rec();
  if (!r.has(id)) return "-That pet is not yours any more.";
  this.sel = id;
  int sl = r.slotOf(id);
  if (this.mode == 0) {
    this.confirm = "";
    return sl == 1 ? @PKG@.PetSnd.slotDone(u, @PKG@.PetOps.takeOut(u, id, by), false) : @PKG@.PetSnd.slotDone(u, @PKG@.PetOps.toSlot(u, id, 1, by), true);
  }
  if (this.mode == 1) {
    this.confirm = "";
    return sl == 2 ? @PKG@.PetSnd.slotDone(u, @PKG@.PetOps.takeOut(u, id, by), false) : @PKG@.PetSnd.slotDone(u, @PKG@.PetOps.toSlot(u, id, 2, by), true);
  }
  boolean fz = this.mode == 2;
  int now = fz ? r.rarityOf(id) : r.rebirthOf(id);
  String fk = fz ? @PKG@.PetOps.fodderKey(r, id) : "";
  String c = (fz ? "fuse|" : "reb|") + id + "|" + now + "|" + fk;
  long cm = @PKG@.PetOps.combatMs(st, ref);
  if (c.equals(this.confirm)) {
    this.confirm = "";
    return @PKG@.PetSnd.slotDone(u, fz ? @PKG@.PetOps.fuse(u, id, now, fk, by, cm) : @PKG@.PetOps.rebirth(u, id, now, by, cm), true);
  }
  String ask = fz ? @PKG@.PetOps.fuseAsk(u, id, cm) : @PKG@.PetOps.rebAsk(u, id, cm);
  this.confirm = ask.startsWith("=") ? c : "";
  return ask;
}""")
M(PAGEC, r"""
public void handleDataEvent(@REF@ ref, @ST@ st, String data) {
  CLICKS = CLICKS + 1L;
  String a0 = jsonStr(data, "a");
  if (a0.startsWith("hub:") && !a0.equals("hub:pets")) clearGrid();     // 0.4.0: never leave a grid tooltip behind
  String hr = @PKG@.HubBar.route(this.playerRef, data, "character", "pets");     // 0.4.2 kit 1.7: row 1 (hub:h:<id>), row 2, the X (null = not a hub click)
  if (hr != null) {
    if (hr.equals("close")) { close(); return; }
    if (hr.equals("self")) { if (this.tab != 0) clearGrid(); this.view = 0; this.tab = 0; this.pg = 0; this.confirm = ""; this.info = ""; rebuild(); return; }     // back to the pets view
    if (!hr.equals("bridge") && !hr.equals("command") && !hr.equals("back")) { this.info = "-That tab could not open right now - try again."; rebuild(); }
    return;
  }
  String a = a0;
  int i = toInt(jsonStr(data, "i"));
  if (a.length() == 4 && a.startsWith("tab") && a.charAt(3) >= '0' && a.charAt(3) <= '2') { i = a.charAt(3) - '0'; a = "tab"; }     // 0.4.2: the sub-tab row
  if (!a.equals("g") && !a.equals("pick") && !a.equals("eg") && !a.equals("slot")) this.confirm = "";     // 0.4.1: + the Hatchery's two-press clicks     // any other click cancels a pending second press
  try {
    if (a.equals("close")) { clearGrid(); close(); return; }
    if (a.equals("tab")) { if (i >= 0 && i < 3 && i != this.tab) { clearGrid(); this.tab = i; this.pg = 0; this.confirm = ""; } this.info = ""; rebuild(); return; }     // 0.4.1
    if (a.equals("emode")) { if (i >= 0 && i < 3) this.emode = i; this.confirm = ""; this.info = ""; rebuild(); return; }
    if (a.equals("eg") && jsonInt(data, "SlotIndex") >= this.eids.length) return;     // an empty Hatchery grid slot: nothing to do
    if (a.equals("later")) { this.later = true; this.view = 0; this.info = ""; rebuild(); return; }     // 0.3.0: the starter view's Later
    if (a.equals("more")) { this.pg = this.pg + 1; this.info = ""; rebuild(); return; }     // 0.4.2: the grid's Show more (no pages)
    if (a.equals("mode")) { if (i >= 0 && i < 4) this.mode = i; this.info = ""; rebuild(); return; }
    if (a.equals("role")) { if (i >= 0 && i < 4) { this.fRole = i; this.pg = 0; } this.info = ""; rebuild(); return; }
    if (a.equals("area")) { if (i >= 0 && i < AREA_SKILLS.length) { this.fArea = i; this.pg = 0; } this.info = ""; rebuild(); return; }
    if (a.equals("g") && jsonInt(data, "SlotIndex") >= this.ids.length) return;     // an empty grid slot: nothing to do (the grid never locks)
    if (!jsonStr(data, "t").equals(this.tok)) { STALE = STALE + 1L; this.confirm = ""; this.info = "=The page changed - here it is again."; rebuild(); return; }
    java.util.UUID u = this.playerRef.getUuid();
    String by = this.playerRef.getUsername();
    if (a.equals("g")) {
      int si = jsonInt(data, "SlotIndex");
      if (si < 0 || si >= this.ids.length) this.info = "-That pet is gone.";
      else this.info = act(u, this.ids[si], by, st, ref);
    } else if (a.equals("out")) {
      if (i < 1 || i > 2 || this.slotIds[i - 1].length() == 0) this.info = "-That slot is empty.";
      else this.info = @PKG@.PetSnd.slotDone(u, @PKG@.PetOps.takeOut(u, this.slotIds[i - 1], by), false);
    } else if (a.equals("pick")) {     // 0.3.0 the starter choice: the first press asks, the second (same row) picks
      String c = "pick|" + i;
      if (c.equals(this.confirm)) {
        this.confirm = "";
        this.info = @PKG@.PetSnd.slotDone(u, @PKG@.PetOps.chooseStarter(u, i, by), true);
        if (this.info.startsWith("+")) { this.view = 0; this.pg = 0; }
      } else { this.info = @PKG@.PetOps.pickAsk(i); this.confirm = this.info.startsWith("=") ? c : ""; }
    }
    else if (a.equals("craft")) {     // 0.4.1 EGGS
      this.confirm = "";
      this.info = i >= 0 && i < @PKG@.PetHatchery.CRAFT.length ? @PKG@.PetHatchery.craft(u, @PKG@.PetInvReal.of(st, ref), @PKG@.PetHatchery.CRAFT[i], by) : "-That egg is gone.";
    } else if (a.equals("slot")) {    // 0.4.1 HATCHERY: Hatch (opens the reel page = no rebuild here) / Take out (two presses)
      String m = slotClick(u, i, jsonStr(data, "m"), by, st, ref);
      if (m == null) return;
      this.info = m;
    } else if (a.equals("eg")) {
      this.info = eggClick(u, jsonInt(data, "SlotIndex"), by, st, ref);
    }
    else this.info = "";
  } catch (Throwable t) {
    @PKG@.PetsLog.warn("pets page click " + a + " failed: " + t);
    this.info = "-Something went wrong. The server log has the details.";
  }
  rebuild();
}""")

