# the frame delays: the 14 / 12 spec curves stretched to pets.hatch.frames and scaled to pets.hatch.reelSeconds (3 s = as written)
M(HPAGE, r"""
public static long delay(int reel, int f, int frames) {
  int[] base = reel == 1 ? @PKG@.PetEggDefs.REEL1 : @PKG@.PetEggDefs.REEL2;
  int n = frames < 2 ? 2 : frames;
  int bi = (int) Math.round((double) f * (double) (base.length - 1) / (double) (n - 1));
  if (bi < 0) bi = 0;
  if (bi >= base.length) bi = base.length - 1;
  double d = (double) base[bi] * (@PKG@.PetsCfg.REEL_S / 3.0) * ((double) base.length / (double) n);
  long ms = Math.round(d);
  return ms < 30L ? 30L : (ms > 3000L ? 3000L : ms);
}""")
# the two strips: reel 1 = pets of this egg drawn with ITS weights, the result at the last frame's centre (index f1 + 1), the cell after it a
# better pet half of the time (a near miss, looks only); reel 2 = the six rarity tokens cycling, the result at the end's centre
M(HPAGE, r"""
public void strips(String cat, int erar) {
  java.util.Random rn = @PKG@.PetEgg.rnd();
  int fr = @PKG@.PetsCfg.REEL_FRAMES;
  this.f1 = fr < 8 ? 8 : (fr > 24 ? 24 : fr);
  this.f2 = this.f1 - 2;
  int n1 = this.f1 + 4;
  this.s1 = new String[n1];
  this.n1 = new String[n1];
  String[] o = @PKG@.PetEgg.order(cat);
  double[] w = @PKG@.PetEgg.catWeights(o, erar);
  int resAt = this.f1 + 1;
  int rank = -1;
  for (int i = 0; i < o.length; i++) if (o[i].equalsIgnoreCase(this.kind)) rank = i;
  for (int i = 0; i < n1; i++) {
    String k = this.kind;
    if (i != resAt && o.length > 0) {
      int p = @PKG@.PetEgg.pick(rn, w);
      if (i == resAt + 1 && rank > 0 && rn.nextBoolean()) p = rn.nextInt(rank);
      if (p >= 0) k = o[p];
    }
    this.s1[i] = portraitOf(k);
    this.n1[i] = @PKG@.PetEgg.kindName(k);
  }
  int n2 = this.f2 + 4;
  this.s2 = new String[n2];
  int res2 = this.f2 + 1;
  for (int i = 0; i < n2; i++) {
    int r = ((this.prar - 1) - res2 + i) % 6;
    if (r < 0) r = r + 6;
    this.s2[i] = @PKG@.PetEggDefs.token(r + 1);
  }
}""")
# one reel's 5 cells + the centre name at frame f (b = a full build or one frame's update)
M(HPAGE, r"""
public void drawReel(@UCB@ b, int reel, int f) {
  String[] s = reel == 1 ? this.s1 : this.s2;
  String x = reel == 1 ? "A" : "B";
  for (int c = 0; c < 5; c++) {
    int i = f + c;
    b.set("#SkyyHt" + x + c + ".Slots", one(s.length == 0 ? null : s[i < s.length ? i : s.length - 1], reel == 2));
  }
  int m = f + 2;
  if (reel == 1) b.set("#SkyyHtAN.Text", this.n1.length == 0 ? "" : this.n1[m < this.n1.length ? m : this.n1.length - 1]);
  else {
    int r = ((this.prar - 1) - (this.f2 + 1) + m) % 6;
    if (r < 0) r = r + 6;
    b.set("#SkyyHtBN.Text", @PKG@.PetKind.rarityName(r + 1));
  }
}""")
M(HPAGE, r"""
public void blankReel(@UCB@ b, int reel) {
  String x = reel == 1 ? "A" : "B";
  for (int c = 0; c < 5; c++) b.set("#SkyyHt" + x + c + ".Slots", one(null, false));
  b.set("#SkyyHt" + x + "N.Text", "?");
}""")
M(HPAGE, r"""
public boolean current() {
  try {
    @REF@ ref = this.playerRef.getReference();
    if (ref == null || !ref.isValid()) return false;
    @ST@ st = ref.getStore();
    @PLA@ p = (@PLA@) st.getComponent(ref, @PLA@.getComponentType());
    return p != null && p.getPageManager().getCustomPage() == this;
  } catch (Throwable t) { return false; }
}""")
M(HPAGE, r"""
public void reveal() {
  if (this.revealed || this.hid.length() == 0) return;
  this.revealed = true;
  // the player left mid-reel: the line waits in the record (hatch.unseen) for the next join (PetEgg.unseen in the tick)
  // only a player still online AND still in a world gets the line now (a dismiss caused by a disconnect keeps hatch.unseen for the join)
  boolean on = false;
  try {
    @PR@ op = @UNI@.get().getPlayer(this.playerRef.getUuid());
    @REF@ orf = op == null || !op.isValid() ? null : op.getReference();
    on = orf != null && orf.isValid() && @PKG@.PetsEng.worldObj(orf.getStore()) != null;
  } catch (Throwable t0) { on = false; }
  if (!on) { @PKG@.PetEgg.ANIM.remove(this.hid); return; }
  try { @PKG@.PetEgg.reveal(this.playerRef.getUuid(), rec(), this.hid); } catch (Throwable t) { @PKG@.PetsLog.warnOnce("reveal:" + t.getClass().getName(), "a hatch reveal failed: " + t); }
}""")
