# portraits + tokens: hidden icon items (Variant, no Categories / Recipe / Interactions - the SkyyMenu icon-item pattern), never obtainable
# an item Icon must live under Icons/ItemsGenerated/ or Icons/Items/ (asset validation, smoke test 2026-10-16): the game's own 128 px MODEL
# icon of the pet's look is copied into the jar at BUILD time as Icons/ItemsGenerated/Skyy_PetIcon_<Kind>.png, box-filtered to the item
# icon size 64 (tools/skyyart.py, pure Python; vanilla-derived bytes go only into the jar, never into a tracked file). Dog / Corgi (no
# model icon) name their skill's vanilla tool icon by path.
import skyyart as _SA


def _half(png):
    im = _SA.png_decode(png)
    if (im.w, im.h) == (64, 64):
        return png
    assert (im.w, im.h) == (128, 128), (im.w, im.h)
    o = _SA.Img(64, 64)
    for y in range(64):
        for x in range(64):
            ps = [im.get(2 * x + dx, 2 * y + dy) for dy in (0, 1) for dx in (0, 1)]
            a = sum(q[3] for q in ps)
            if a == 0:
                continue
            o.put(x, y, (sum(q[0] * q[3] for q in ps) / float(a), sum(q[1] * q[3] for q in ps) / float(a), sum(q[2] * q[3] for q in ps) / float(a), a / 4.0))
    return _SA.png_encode(o)


# kinds that wear ANOTHER kind's model (critic: Tusker = the Warthog look) get a tinted copy so every portrait differs (Tusker = the red
# war-hog of the pet art: red up, green / blue down)
PORTRAIT_TINT = {"Tusker": (1.25, 0.62, 0.55)}


def _tint(png, m):
    im = _SA.png_decode(png)
    for y in range(im.h):
        for x in range(im.w):
            c = im.get(x, y)
            if c[3]:
                im.put(x, y, (c[0] * m[0], c[1] * m[1], c[2] * m[2], c[3]))
    return _SA.png_encode(im)


